policy:
{
  // An ipset is a named list of addresses (CIDRs, single IPs, a-b ranges,
  // host: refs, or nested ipsets). Tailground expands ipset:<name> to its
  // members before compiling. Here the CI runners need two internal services
  // that aren't tailnet devices — 100.64.0.20 (registry) and .21 (cache).
  //
  // Add a grant: tag:ci reaches ipset:build-deps on 443.
  "ipsets": {
    "ipset:build-deps": ["100.64.0.20/32", "100.64.0.21/32"],
  },
  "tagOwners": {
    "tag:ci": ["alice@example.com"],
  },
  "grants": [
    // TODO
  ],
  "tests": [
    { "src": "tag:ci", "accept": ["100.64.0.20:443", "100.64.0.21:443"], "deny": ["100.64.0.20:22", "100.64.0.99:443"] },
  ],
}
